<?php
require 'config.php'; require 'includes/functions.php';
$id=(int)($_GET['id']??0); $s=$pdo->prepare('SELECT * FROM products WHERE id=? AND active=1'); $s->execute([$id]); $product=$s->fetch();
if(!$product){http_response_code(404);$pageTitle='Product not found';require 'includes/header.php';echo '<div class="panel"><h1>Product not found</h1><a class="btn" href="index.php">Back to shop</a></div>';require 'includes/footer.php';exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$qty=max(1,min(99,(int)($_POST['quantity']??1)));$_SESSION['cart']=$_SESSION['cart']??[];$_SESSION['cart'][$id]=min(99,(int)($_SESSION['cart'][$id]??0)+$qty);$_SESSION['flash']=$product['name'].' added to your basket.';redirect('cart.php');}
$pageTitle=$product['name'];require 'includes/header.php';?>
<div class="product-detail"><div class="product-detail-image"><?php if($product['image']&&is_file($product['image'])):?><img src="<?=e($product['image'])?>" alt="<?=e($product['name'])?>"><?php else:?><span class="no-image">Product photo coming soon</span><?php endif;?></div><div class="product-detail-info"><div class="eyebrow"><?=e($product['category'])?></div><h1><?=e($product['name'])?></h1><div class="price detail-price"><?=money($product['price'])?></div><p><?=nl2br(e($product['description']??''))?></p><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label for="quantity">Quantity</label><input id="quantity" name="quantity" type="number" min="1" max="99" value="1" required style="max-width:120px"></div><button class="btn">Add to basket</button></form><p class="muted small">You can keep browsing and pay when you're ready. Checkout requires a paid R50 membership.</p><a href="index.php">← Continue shopping</a></div></div>
<?php require 'includes/footer.php';?>